#include "modules/fem_system_api.h"
#include "runtime/thread_budget.hpp"
#include <algorithm>
#include <atomic>
#include <cmath>
#include <cstring>
#include <iostream>
#include <memory>
#include <vector>
namespace {
unsigned checks=0,failures=0;void verify(bool okay,const char* text){++checks;if(!okay){++failures;std::cerr<<"FAIL "<<text<<'\n';}}
struct Host {std::shared_ptr<std::atomic_bool> cancel=std::make_shared<std::atomic_bool>(false);penta::runtime::ParallelStatistics stats;unsigned threads=4;static int cancelled(void* raw){return static_cast<Host*>(raw)->cancel->load();}static int charge(void*,uint64_t,char*,uint64_t){return 0;}static int parallel(void* raw,uint64_t n,uint64_t cost,penta_numeric_range_task_v1 fn,void* data,char* error,uint64_t cap){auto& self=*static_cast<Host*>(raw);std::string text;penta::runtime::ParallelStatistics stats;const auto status=penta::runtime::ThreadBudget::instance().run(n,cost,fn,data,{self.threads,1},self.cancel,stats,text);self.stats.parallelCalls+=stats.parallelCalls;self.stats.threadsUsed=std::max(self.stats.threadsUsed,stats.threadsUsed);if(error&&cap){std::strncpy(error,text.c_str(),cap-1);error[cap-1]=0;}return status;}};
struct Mesh {std::vector<double> points,parameters;std::vector<uint64_t> faces,boundaries;unsigned dimension=2;explicit Mesh(unsigned n,unsigned d=2):dimension(d){for(unsigned y=0;y<=n;++y)for(unsigned x=0;x<=n;++x){const double u=static_cast<double>(x)/n,v=static_cast<double>(y)/n;parameters.insert(parameters.end(),{u,v});points.push_back(u);points.push_back(v);if(d>=3)points.push_back(u*u+v*v);if(d>=4)points.push_back(2*u);if(d>=5)points.push_back(3*v);}auto id=[&](unsigned x,unsigned y){return static_cast<uint64_t>(y*(n+1)+x+1);};for(unsigned y=0;y<n;++y)for(unsigned x=0;x<n;++x)faces.insert(faces.end(),{id(x,y),id(x+1,y),id(x+1,y+1),id(x,y),id(x+1,y+1),id(x,y+1)});for(unsigned k=0;k<n;++k)boundaries.insert(boundaries.end(),{id(0,k),id(0,k+1),1,id(n,k),id(n,k+1),2,id(k,0),id(k+1,0),3,id(k,n),id(k+1,n),4});}};
struct Model {unsigned mode=0;std::vector<double> diffusion;static int reaction(void* raw,const double* u,uint32_t c,const double*,uint32_t,double* result,double* jac,char*,uint64_t){const auto mode=static_cast<Model*>(raw)->mode;for(unsigned i=0;i<c;++i){result[i]=mode==2?0:mode==3?u[i]:u[i]*u[i]*u[i];if(jac)for(unsigned j=0;j<c;++j)jac[i*c+j]=i==j?(mode==2?0:mode==3?1:3*u[i]*u[i]):0;}return 0;}static int forcing(void* raw,const double* point,uint32_t,double* result,uint64_t c,char*,uint64_t){const auto& self=*static_cast<Model*>(raw);const auto x=point[0],y=point[1],u=x*(1-x)*y*(1-y),lap=2*(x*(1-x)+y*(1-y));for(uint64_t i=0;i<c;++i){if(self.mode==2)result[i]=0;else if(self.mode==3)result[i]=1;else if(self.mode==4){const auto r2=x*x+y*y;result[i]=8*x*(1+2*r2)/std::pow(1+4*r2,2)+x*x*x;}else{long double coupled=0;for(uint64_t j=0;j<c;++j)coupled+=(self.diffusion.empty()?(i==j?1:0):self.diffusion[i*c+j])*(j+1);result[i]=static_cast<double>(coupled)*lap+std::pow((i+1)*u,3);}}return 0;}static int exact(void* raw,const double* point,uint32_t,double* result,uint64_t c,char*,uint64_t){const auto mode=static_cast<Model*>(raw)->mode;for(uint64_t i=0;i<c;++i)result[i]=mode==2?point[0]+point[1]:mode==3?1:mode==4?point[0]:(i+1)*point[0]*(1-point[0])*point[1]*(1-point[1]);return 0;}static int geometry(void*,const double* uv,uint32_t d,double* point,double* jac,char*,uint64_t){point[0]=uv[0];point[1]=uv[1];if(d>=3)point[2]=uv[0]*uv[0]+uv[1]*uv[1];if(d>=4)point[3]=2*uv[0];if(d>=5)point[4]=3*uv[1];if(jac){std::fill_n(jac,2*d,0.);jac[0]=jac[3]=1;if(d>=3){jac[4]=2*uv[0];jac[5]=2*uv[1];}if(d>=4)jac[6]=2;if(d>=5)jac[9]=3;}return 0;}static int boundary(void* raw,uint64_t tag,const double* point,const double* normal,uint32_t,double* value,double* alpha,char*,uint64_t){const auto mode=static_cast<Model*>(raw)->mode;if(mode==2){value[0]=point[0]+point[1];if(tag==2||tag==4){*alpha=2;value[0]=normal[0]+normal[1]+2*(point[0]+point[1]);}}else if(mode==3)value[0]=1;else if(mode==4)value[0]=point[0];return 0;}};
struct Output {int status=0;penta_fem_system_result_v1 result{};std::vector<double> points,values,visPoints,visValues;std::vector<uint64_t> visFaces,elementDofs;std::string error;penta::runtime::ParallelStatistics stats;};
Output run(const Mesh& mesh,Model& model,unsigned order,unsigned components=1,Host* external=nullptr){Host owner;auto& host=external?*external:owner;penta_fem_parallel_host_v1 h{};h.base={sizeof(h),PENTA_FEM_ABI_V1,&host,Host::cancelled,Host::charge};h.threads_requested=h.threads_granted=host.threads;h.parallel_for=Host::parallel;penta_fem_system_request_v1 q{};q.struct_size=sizeof(q);q.dimension=mesh.dimension;q.components=components;q.order=order;q.visualization_refinement=4;q.vertices=mesh.points.size()/mesh.dimension;q.triangles=mesh.faces.size()/3;q.boundaries=mesh.boundaries.size()/3;q.points=mesh.points.data();q.faces=mesh.faces.data();q.boundary_tags=mesh.boundaries.data();q.diffusion=1;q.diffusion_block=model.diffusion.empty()?nullptr:model.diffusion.data();q.rtol=1e-10;q.atol=1e-12;q.linear_tolerance=1e-11;q.max_seconds=60;q.max_newton=30;q.max_linear=1000;q.gmres_restart=40;q.max_work=1000000000;q.max_bytes=512*1024*1024;q.reaction=Model::reaction;q.reaction_context=&model;q.forcing=Model::forcing;q.forcing_context=&model;q.exact=Model::exact;q.exact_context=&model;q.boundary=Model::boundary;q.boundary_context=&model;if(mesh.dimension>2){q.geometry=Model::geometry;q.parameter_points=mesh.parameters.data();}penta_fem_system_boundary_condition_v1 conditions[]{{2,PENTA_FEM_SYSTEM_ROBIN,0,nullptr,2},{4,PENTA_FEM_SYSTEM_ROBIN,0,nullptr,2}};if(model.mode==2){q.conditions=conditions;q.boundary_conditions=2;}const uint64_t local=(order+1)*(order+2)/2,capacity=q.vertices+q.triangles*local,visVertices=q.triangles*15,visTriangles=q.triangles*16;Output out;out.points.resize(capacity*mesh.dimension);out.values.resize(capacity*components);out.visPoints.resize(visVertices*mesh.dimension);out.visValues.resize(visVertices*components);out.visFaces.resize(3*visTriangles);out.elementDofs.resize(q.triangles*local);auto& r=out.result;r.struct_size=sizeof(r);r.dof_capacity=capacity;r.vertex_capacity=visVertices;r.triangle_capacity=visTriangles;r.dof_coordinates=out.points.data();r.dof_values=out.values.data();r.visualization_coordinates=out.visPoints.data();r.visualization_values=out.visValues.data();r.visualization_faces=out.visFaces.data();r.element_dofs=out.elementDofs.data();char error[1024]{};penta::runtime::ThreadBudget::instance().withReservation([&]{out.status=penta_fem_system_query_v1(PENTA_FEM_SYSTEM_ABI_V1)->solve(&h.base,&q,&r,error,sizeof(error));});out.error=error;out.stats=host.stats;if(out.status)std::cerr<<"fem system status "<<out.status<<": "<<error<<'\n';return out;}
}
int main(){Model scalar;Mesh mesh(1);auto p4=run(mesh,scalar,4);verify(!p4.status&&p4.result.converged,"nonlinear P4 scalar FEM converges");verify(!p4.status&&p4.result.l2_error<1e-9&&p4.result.jacobian_evaluations>0,"independent degree4 manufactured nonlinear polynomial and generated Jacobian");if(!p4.status){double reference[]{.2,.3,.1,.2,.4,.1};uint64_t faces[]{1,2,1};double sampled[3]{};penta_fem_system_evaluate_request_v1 q{};q.struct_size=sizeof(q);q.order=4;q.components=1;q.dofs=p4.result.dofs;q.triangles=2;q.queries=3;q.max_work=100000;q.max_bytes=1048576;q.max_seconds=10;q.values=p4.values.data();q.reference_points=reference;q.face_ids=faces;q.element_dofs=p4.elementDofs.data();penta_fem_system_evaluate_result_v1 r{sizeof(r),0,3,0,sampled};Host owner;penta_fem_host_v1 host{sizeof(host),PENTA_FEM_ABI_V1,&owner,Host::cancelled,Host::charge};char error[1024]{};const auto status=penta_fem_system_query_v1(PENTA_FEM_SYSTEM_ABI_V1)->evaluate(&host,&q,&r,error,sizeof(error));double maximum=0;for(unsigned k=0;k<3;++k){const auto u=reference[2*k],v=reference[2*k+1],x=faces[k]==1?u+v:u,y=faces[k]==1?v:u+v;maximum=std::max(maximum,std::abs(sampled[k]-x*(1-x)*y*(1-y)));}verify(!status&&maximum<1e-10,"native reference H1 evaluation preserves exact P4 fields");}Model vector;vector.diffusion.assign(25,0);for(unsigned i=0;i<5;++i)vector.diffusion[5*i+i]=1;vector.diffusion[1]=.2;vector.diffusion[5]=-.2;auto all=run(mesh,vector,4,5);verify(!all.status&&all.result.converged&&all.result.l2_error<1e-8,"full five-coordinate nonsymmetric coupled diffusion/nonlinear P4 system");bool retained=true;if(!all.status)for(uint64_t node=0;node<all.result.dofs;++node){const auto x=all.points[2*node],y=all.points[2*node+1];retained=retained&&std::abs(all.values[5*node+4]-5*x*(1-x)*y*(1-y))<1e-8;}verify(retained,"all five retained nodal coefficients match an independent exact field");Model mixed;mixed.mode=2;auto boundary=run(Mesh(3),mixed,2);verify(!boundary.status&&boundary.result.converged&&boundary.result.l2_error<1e-8,"mixed native Dirichlet/Robin conormal data reproduce a linear manufactured solution");Model curved;curved.mode=4;auto surface=run(Mesh(4,3),curved,3);verify(!surface.status&&surface.result.converged&&surface.result.l2_error<1e-6&&surface.result.geometry_evaluations>0,"curved native paraboloid FEM uses the true quadrature metric and analytic surface forcing");Model constant;constant.mode=3;auto five=run(Mesh(2,5),constant,3);verify(!five.status&&five.result.converged&&five.result.l2_error<1e-8,"curved5D embedded H1 field preserves native manifold coordinates");bool complete=true;if(!five.status)for(uint64_t at=0;at<five.result.dofs;++at)complete=complete&&std::abs(five.points[5*at+3]-2*five.points[5*at])<1e-12&&std::abs(five.points[5*at+4]-3*five.points[5*at+1])<1e-12;verify(complete,"fourth/fifth geometry coordinates are never truncated by MFEM3D vertices");Host serial;serial.threads=1;auto serialField=run(Mesh(4),scalar,2,1,&serial);Host parallel;parallel.threads=4;auto parallelField=run(Mesh(4),scalar,2,1,&parallel);verify(!serialField.status&&!parallelField.status&&parallelField.result.converged&&parallelField.stats.parallelCalls>0,"nonlinear FEM assembly and Krylov kernels use the shared CPU allowance");double difference=0;if(!serialField.status&&!parallelField.status)for(uint64_t at=0;at<serialField.result.dofs;++at)difference=std::max(difference,std::abs(serialField.values[at]-parallelField.values[at]));verify(difference<1e-9,"serial/parallel native nonlinear fields agree");Host cancelled;cancelled.cancel->store(true);verify(run(mesh,scalar,2,1,&cancelled).status==3,"system FEM cancellation");verify(!penta_fem_system_query_v1(99),"system FEM capability ABI check");std::cout<<checks<<" nonlinear FEM checks, "<<failures<<" failures\n";return failures?1:0;}
